import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();

  // Plane geometry – size based on typical card dimensions
  const geometry = new PlaneGeometry(7, 6);
  const material = new MeshBasicNodeMaterial();
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously; material will be updated when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Apply cinematic primitives from config
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const handle = fn(root, prim.params);
        primitiveHandles.push(handle);
      }
    }
  }

  // GSAP timelines for interactions
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(root.position, {
    y: '+=0.15',
    duration: 0.7,
    ease: 'power3.out',
  });

  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline.to(root.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(1)',
  });

  // Interaction handlers attached to userData
  root.userData.handlers = {
    hover: (enter) => {
      if (enter) hoverTimeline.play();
      else hoverTimeline.reverse();
    },
    click: () => {
      pressTimeline.restart();
      ctx.emit('hub-journal.select', {});
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    material.dispose();
    geometry.dispose();
    hoverTimeline.kill();
    pressTimeline.kill();
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
  };

  return root;
}
